    fun test_64_getOnResourcShowsFaults_109_202()  {
        
        given().accept("text/plain")
                .header("Authorization", "U5") // U5
                .get("${baseUrlOfSut}/api/resources/664")
                .then()
                .statusCode(200)
                .assertThat()
                .contentType("text/plain")
                .body(containsString("U5"))
        
        given().accept("*/*")
                .header("Authorization", "U1") // U1
                .get("${baseUrlOfSut}/api/resources/664")
                .then()
                .statusCode(403)
                .assertThat()
                .body(isEmptyOrNullString())
        
        // Fault109. HTTP Violation: no-401-if-no-authenticate.
        // Fault202. Schema Violation: no-401-if-no-auth.
        given().accept("*/*")
                .get("${baseUrlOfSut}/api/resources/664")
                .then()
                .statusCode(401)
                .assertThat()
                .header("www-authenticate", isEmptyOrNullString())
                .body(isEmptyOrNullString())
    }
    
    
